INSERT INTO feature VALUES('mutation-testing','workflow','Mutation testing',NULL,'partial','notable',NULL,'A mutation campaign maps each crate''s surviving mutants, and each survivor becomes a witness or an equivalence with its probe; a run tests each mutant under the witnesses that name its item, building and linking only the test binaries those witnesses live in. One build serves the mutants of a crate: each mutated function body becomes a match on the mutant that the test process selects, and a mutant that the schema cannot hold builds alone. Each outcome keeps a key of its content, the crate''s files and those of its workspace dependencies, the toolchain and the settings, so a run builds nothing for an outcome whose inputs stand; a run is held in a scope capped at 16 GB with no swap, one run a host.','kernel-core core-checker surface-dispatcher surface-driver surface-lsp storage-records surface-layout',NULL,NULL,'#512 #510 #3207');
